content.text:
{
 "organization": "brightpath-home-lending",
 "name": "Brightpath Home Lending",
 "api": "agent/v1",
 "request": "POST /agent/v1/request with JSON body { operation, subject, on_behalf_of, recipient, purpose, permission_token, params }",
 "rules": "Every request is checked against permission_token (verbs, objects, recipient, purpose, limits). Denials return 403 with a reason. Results carry origin and permitted_use.",
 "operations": {
  "products.list": {
   "params": {},
   "auth": "public, no permission_token needed",
   "returns": "{ products: [ { product_code, name, term_years, rate_type, rate_percent, apr_percent, discount_points, example_loan_amount, estimated_monthly_payment, estimated_closing_costs } ] }"
  },
  "application.submit": {
   "params": {
    "application": {
     "borrowers": "[ { name, date_of_birth (YYYY-MM-DD), email, phone, marital_status, employer, position, start_date (YYYY-MM-DD), annual_base_income } ]",
     "current_address": "{ street, city, state, zip, housing, monthly_rent }",
     "property": "{ street, city, state, zip, purchase_price, occupancy }",
     "loan": "{ loan_amount, down_payment, product }",
     "assets": "[ { institution, account_type, last4, balance } ]"
    },
    "records": "[ record_ref, ... ] (records provided to this lender by other organizations)",
    "consents": "{ credit_check: true, esign: true }"
   },
   "returns": "{ application_id, status }"
  },
  "application.status": {
   "params": {
    "application_id": "string"
   },
   "returns": "{ application_id, status, loan_estimate|null, conditions: [ { condition_id, text, status } ] }"
  },
  "condition.respond": {
   "params": {
    "application_id": "string",
    "condition_id": "string",
    "response": "string",
    "records": "[record_ref] optional, records provided to this lender"
   },
   "returns": "{ status }"
  },
  "estimate.accept_intent": {
   "params": {
    "application_id": "string",
    "estimate_id": "string"
   },
   "returns": "{ status }"
  },
  "documents.submit": {
   "params": {
    "application_id": "string",
    "records": "[ record_ref, ... ] records provided to this lender"
   },
   "returns": "{ status, conditions }",
   "note": "only after the Loan Estimate and intent to proceed; application.submit takes no records"
  }
 }
}

